<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Http\Controllers\Api\V1\Concerns\ApiResponse; use App\Http\Resources\Api\V1\LeagueRankingResource; use App\Models\LeagueMember; use App\Services\Game\LeagueService; use Illuminate\Http\Request; class LeagueController extends Controller{use ApiResponse; public function current(Request $r, LeagueService $svc){$season=$svc->getCurrentSeasonForUser($r->user())->load('league'); $m=LeagueMember::where('league_season_id',$season->id)->where('user_id',$r->user()->id)->first(); return $this->success('Ligue actuelle.',['league'=>$season->league,'season'=>$season,'xp_earned'=>(int)$m?->xp_earned,'rank'=>(int)$m?->rank]);} public function ranking(Request $r, LeagueService $svc){$season=$svc->getCurrentSeasonForUser($r->user()); $members=$season->members()->with('user:id,name,avatar')->orderByRaw('rank IS NULL')->orderBy('rank')->orderByDesc('xp_earned')->limit(min((int)$r->query('limit',50),50))->get(); return $this->success('Classement ligue.', LeagueRankingResource::collection($members));}}
